"""Codex-native tool projection, failure classification, and retry deadlines."""

import json
import re
from datetime import UTC, datetime, timedelta

from ovcaq.events.model import (
    FailureClass,
    JSONValue,
    ObservationType,
    Usage,
    sanitize_json,
    sanitize_text,
)


def item_activity(item: object) -> dict[str, JSONValue] | None:
    if not isinstance(item, dict):
        return None
    item_id = item.get("id")
    item_kind = item.get("type")
    if not isinstance(item_id, str) or not item_id:
        return None
    detail = item.get("message" if item_kind == "error" else "text")
    if item_kind in ("agent_message", "reasoning", "error") and isinstance(detail, str):
        return {
            "kind": {
                "agent_message": "text",
                "reasoning": "thinking",
                "error": "error",
            }[item_kind],
            "text": sanitize_text(detail)[:4096],
            "message_id": sanitize_text(item_id)[:4096],
        }
    if item_kind == "todo_list":
        steps = item.get("items")
        if isinstance(steps, list) and all(
            isinstance(step, dict)
            and isinstance(step.get("text"), str)
            and isinstance(step.get("completed"), bool)
            for step in steps
        ):
            return {
                "kind": "plan",
                "message_id": sanitize_text(item_id)[:4096],
                "items": [
                    {
                        "text": sanitize_text(step["text"])[:4096],
                        "completed": step["completed"],
                    }
                    for step in steps
                ],
            }
    return None


def bounded_detail(detail: str) -> str:
    """Redact original and control-reconstructed credentials, then bound detail."""
    controls = r"\x1b\[[0-?]*[ -/]*[@-~]|[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]"
    # A lone ESC must not turn a new [REDACTED] marker into an ANSI sequence.
    protected = re.sub(
        controls,
        lambda match: "\x00" if match[0] == "\x1b" else match[0],
        detail,
    )
    cleaned = re.sub(controls, "", sanitize_text(protected))
    return sanitize_text(cleaned)[:4096]


def turn_usage(native: object) -> tuple[Usage, str | None]:
    """Normalize cumulative counters without inventing a cache partition."""
    if not isinstance(native, dict):
        return Usage(), "Missing or malformed Codex usage"
    names = (
        "input_tokens",
        "cached_input_tokens",
        "cache_write_input_tokens",
        "output_tokens",
        "reasoning_output_tokens",
    )
    counts: list[int | None] = []
    gap = None
    for name in names:
        value = native.get(name)
        if type(value) is int and value >= 0:
            counts.append(value)
        else:
            counts.append(None)
            if name in native or name in names[:3]:
                gap = "Missing or invalid Codex usage counter"
    if all(value == 0 for value in counts):
        return Usage(), "Default zero Codex usage lacks telemetry"
    inclusive, read, write, output, _reasoning = counts
    uncached = None
    estimated = write is not None and write > 0
    if estimated:
        gap = "; ".join(
            reason
            for reason in (gap, "Codex cache-write input partition is unknown")
            if reason
        )
    elif inclusive is not None and read is not None and write == 0:
        if read <= inclusive:
            uncached = inclusive - read
        else:
            gap = "; ".join(
                reason
                for reason in (gap, "Codex cache reads exceed inclusive input")
                if reason
            )
    return Usage(
        input_tokens=uncached,
        output_tokens=output,
        cache_creation_input_tokens=write,
        cache_read_input_tokens=read,
        estimated=estimated,
    ), gap


def command_detail(item: dict[str, object]) -> str | None:
    command, output, exit_code = (
        item.get("command"),
        item.get("aggregated_output"),
        item.get("exit_code"),
    )
    if not isinstance(command, str) or not isinstance(output, str):
        return None
    if exit_code is not None and type(exit_code) is not int:
        return None
    return sanitize_text(f"{command}\n{output}")[:4096]


def file_detail(item: dict[str, object]) -> str | None:
    changes = item.get("changes")
    if not isinstance(changes, list) or not all(
        isinstance(change, dict)
        and isinstance(change.get("path"), str)
        and change.get("kind") in ("add", "delete", "update")
        for change in changes
    ):
        return None
    return sanitize_text(
        "; ".join(f"{change['kind']}: {change['path']}" for change in changes)
    )[:4096]


def mcp_detail(item: dict[str, object]) -> str | None:
    if not all(isinstance(item.get(key), str) for key in ("server", "tool")):
        return None
    result, error = item.get("result"), item.get("error")
    if result is not None and (
        not isinstance(result, dict) or not isinstance(result.get("content"), list)
    ):
        return None
    if error is not None and (
        not isinstance(error, dict) or not isinstance(error.get("message"), str)
    ):
        return None
    detail = {key: item.get(key) for key in ("server", "tool", "result", "error")}
    return json.dumps(sanitize_json(detail), ensure_ascii=False)[:4096]


def web_detail(item: dict[str, object]) -> str | None:
    action = item.get("action")
    if not isinstance(item.get("query"), str) or not isinstance(action, dict):
        return None
    action_kind = action.get("type")
    if not isinstance(action_kind, str):
        return None
    fields = {
        "search": ("query",),
        "open_page": ("url",),
        "find_in_page": ("url", "pattern"),
    }.get(action_kind, ())
    if any(
        action.get(key) is not None and not isinstance(action[key], str)
        for key in fields
    ):
        return None
    queries = action.get("queries")
    if (
        action_kind == "search"
        and queries is not None
        and (
            not isinstance(queries, list)
            or not all(isinstance(query, str) for query in queries)
        )
    ):
        return None
    if "results" in item and not isinstance(item["results"], list):
        return None
    detail = {key: item.get(key) for key in ("query", "action", "results")}
    return json.dumps(sanitize_json(detail), ensure_ascii=False)[:4096]


def collab_detail(item: dict[str, object]) -> str | None:
    if item.get("tool") not in ("spawn_agent", "send_input", "wait", "close_agent"):
        return None
    if not isinstance(item.get("sender_thread_id"), str):
        return None
    prompt = item.get("prompt")
    if prompt is not None and not isinstance(prompt, str):
        return None
    return sanitize_text(prompt or "")[:4096]


def item_lanes(
    item: object,
    started_lanes: set[str] | None = None,
) -> tuple[list[tuple[str, ObservationType, dict[str, JSONValue]]], bool]:
    if not isinstance(item, dict) or item.get("type") != "collab_tool_call":
        return [], False
    receivers, states = item.get("receiver_thread_ids"), item.get("agents_states")
    if not isinstance(receivers, list) or not receivers or not isinstance(states, dict):
        return [], True
    kinds = {
        "pending_init": ObservationType.LANE_PROGRESS,
        "running": ObservationType.LANE_PROGRESS,
        "completed": ObservationType.LANE_COMPLETED,
        "errored": ObservationType.LANE_FAILED,
    }
    result: list[tuple[str, ObservationType, dict[str, JSONValue]]] = []
    has_unknown = False
    for receiver in receivers:
        if not isinstance(receiver, str) or not receiver:
            has_unknown = True
            continue
        state = states.get(receiver)
        if not isinstance(state, dict):
            has_unknown = True
            continue
        status, message = state.get("status"), state.get("message")
        if (
            status in ("interrupted", "shutdown", "not_found")
            and started_lanes is not None
            and receiver in started_lanes
        ):
            status = "errored"
        if (
            not isinstance(status, str)
            or status not in kinds
            or (message is not None and not isinstance(message, str))
        ):
            has_unknown = True
            continue
        result.append(
            (
                receiver,
                kinds[status],
                {"label": "Receiver", "detail": bounded_detail(message or "")},
            )
        )
    return result, has_unknown


def item_tool(
    item: object,
    event: str,
) -> tuple[ObservationType, dict[str, JSONValue]] | None:
    if not isinstance(item, dict):
        return None
    item_id, item_kind = item.get("id"), item.get("type")
    if not isinstance(item_id, str) or not item_id or not isinstance(item_kind, str):
        return None
    projections = {
        "command_execution": ("command", command_detail),
        "file_change": ("file change", file_detail),
        "mcp_tool_call": ("remote tool", mcp_detail),
        "web_search": ("web search", web_detail),
        "collab_tool_call": ("collaboration", collab_detail),
    }
    projection = projections.get(item_kind)
    if projection is None:
        return None
    name, project = projection
    detail = project(item)
    if detail is None:
        return None
    status = item.get("status")
    if item_kind == "web_search":
        status = "completed" if event == "item.completed" else "in_progress"
    allowed = ("in_progress", "completed", "failed")
    if status not in allowed + (
        ("declined",) if item_kind == "command_execution" else ()
    ):
        return None
    failed = (
        item_kind == "command_execution" and item.get("exit_code") not in (None, 0)
    ) or (item_kind == "mcp_tool_call" and item.get("error") is not None)
    kind = ObservationType.TOOL_STARTED
    if failed or status in ("failed", "declined"):
        kind = ObservationType.TOOL_FAILED
    elif status == "completed":
        kind = ObservationType.TOOL_COMPLETED
    return kind, {"tool_id": item_id, "name": name, "detail": detail}


def classify_failure(detail: str) -> FailureClass:
    """Match native diagnostics in authentication-to-agent precedence order."""
    status = (
        r"(?:http(?:/\d+(?:\.\d+)?| status(?: (?:client|server) error \()?)?"
        r"|status(?: code)?|error code)\s*:?\s*"
    )
    for failure, pattern in (
        (
            FailureClass.AUTHENTICATION,
            (
                rf"{status}401|unauthorized|not logged in|"
                r"(?:invalid|expired) credentials?"
            ),
        ),
        (
            FailureClass.PERMISSION,
            rf"{status}403|permission denied|sandbox (?:denied|error)|approval denied",
        ),
        (
            FailureClass.RATE_LIMIT,
            (
                rf"{status}429|rate[- ]limit(?:s|ed|ing)?|quota (?:limits?|exceeded)|"
                r"usage limits?"
            ),
        ),
        (
            FailureClass.CONNECTIVITY,
            (
                rf"{status}(?:502|503)|connection reset|connection refused|"
                r"connection failed|dns|network unreachable|server unavailable|"
                r"stream disconnected|model is at capacity"
            ),
        ),
        (FailureClass.TIMEOUT, r"timeouts?|timed out"),
        (
            FailureClass.AGENT,
            r"agent failed|agent failure|internal error|agent loop died",
        ),
    ):
        if re.search(rf"\b(?:{pattern})\b", detail, re.IGNORECASE):
            return failure
    return FailureClass.UNKNOWN


def failure_reset(detail: str, now: datetime) -> datetime | None:
    """Return only an explicit aware deadline within the next six hours."""
    absolute = re.search(r"\breset at (\S+)", detail, re.IGNORECASE)
    relative = re.search(r"\bretry after (\S+) seconds?\b", detail, re.IGNORECASE)
    try:
        if absolute:
            reset = datetime.fromisoformat(absolute[1].rstrip(".,)"))
            if reset.tzinfo is None:
                return None
        elif relative:
            seconds = float(relative[1])
            if not 0 < seconds <= 21600:
                return None
            reset = now + timedelta(seconds=seconds)
        else:
            return None
        if not timedelta(0) < reset - now <= timedelta(hours=6):
            return None
        return reset.astimezone(UTC)
    except (ValueError, OverflowError):
        return None

"""Configuration-driven Codex launch adapter."""

import hashlib
import json
import logging
import os
import selectors
import subprocess
from collections.abc import Iterable
from dataclasses import asdict, replace
from datetime import UTC, datetime
from time import monotonic

from ovcaq.config import AgentSettings
from ovcaq.drivers.base import DriverHealth, LaunchRequest, LaunchSpec
from ovcaq.drivers.codex_events import (
    bounded_detail,
    classify_failure,
    failure_reset,
    item_activity,
    item_lanes,
    item_tool,
    turn_usage,
)
from ovcaq.events import Observation, SessionSummary
from ovcaq.events.model import (
    PROTOCOL_VERSION,
    FailureClass,
    JSONValue,
    ObservationType,
    Usage,
    sanitize_text,
)
from ovcaq.events.reducer import reduce_session

logger = logging.getLogger(__name__)

_PINNED_VERSION = "0.160.0"
_PROBE_OUTPUT_LIMIT = 16 * 1024


def _run_probe_command(
    command: tuple[str, ...], environment: dict[str, str]
) -> tuple[int, bytearray, bytearray]:
    deadline = monotonic() + 5
    with (
        subprocess.Popen(
            command,
            env=environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            bufsize=0,
        ) as process,
        selectors.DefaultSelector() as selector,
    ):
        assert process.stdout is not None and process.stderr is not None
        stdout, stderr = bytearray(), bytearray()
        buffers = {
            process.stdout.fileno(): stdout,
            process.stderr.fileno(): stderr,
        }
        for stream in (process.stdout, process.stderr):
            selector.register(stream, selectors.EVENT_READ)
        try:
            while selector.get_map():
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise subprocess.TimeoutExpired(process.args, 5)
                for key, _ in selector.select(remaining):
                    chunk = os.read(key.fd, 4096)
                    if not chunk:
                        selector.unregister(key.fileobj)
                        continue
                    buffer = buffers[key.fd]
                    buffer.extend(chunk[: _PROBE_OUTPUT_LIMIT - len(buffer)])
            exit_code = process.wait(timeout=max(0, deadline - monotonic()))
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()
            raise
    return exit_code, stdout, stderr


def _probe_failure(
    executable: str, label: str, exit_code: int, stdout: bytearray, stderr: bytearray
) -> DriverHealth:
    diagnostics = sanitize_text(
        stdout.decode("utf-8", errors="replace")
        + "\n"
        + stderr.decode("utf-8", errors="replace")
    ).strip()
    hint = "; run codex login" if label == "authentication" else ""
    detail = (
        f"{executable}: {label} check failed (exit code {exit_code})"
        f"{hint}: {diagnostics}"
    )
    return DriverHealth(
        False,
        detail.encode("utf-8")[:_PROBE_OUTPUT_LIMIT].decode("utf-8", errors="ignore"),
    )


_DEFAULT_PROMPT = """Read the committed OVCAQ state to determine the current phase. Use `ovcaq state`
and `ovcaq workflow` commands for all durable mutations. Perform only the
current phase, commit exactly one successful phase handoff through the OVCAQ
workflow command, then exit the session. Never edit state.json directly. Do not
start a second phase in this session. Completion is determined by committed
state, not your final message. Do not install, upgrade, or modify launcher
plugins or marketplace content."""


class CodexDriver:
    name = "codex"

    def __init__(self, settings: AgentSettings, *, run_id: str) -> None:
        options = settings.options
        unknown = options.keys() - {"sandbox", "approval", "allow_explicit_model"}
        if unknown:
            raise ValueError(f"Unknown Codex options: {sorted(unknown)}")
        if options.get("sandbox", "workspace-write") != "workspace-write":
            raise ValueError("Codex sandbox must be workspace-write")
        if options.get("approval", "never") != "never":
            raise ValueError("Codex approval must be never")
        if type(options.get("allow_explicit_model", False)) is not bool:
            raise ValueError("Codex allow_explicit_model must be a boolean")
        self._settings = settings
        self._run_id = run_id
        self._session_id: str | None = None
        self._usage = Usage()
        self._thread_conflict = False
        self._identities: dict[tuple[str, str], bool] = {}

    def build_launch(self, request: LaunchRequest) -> LaunchSpec:
        settings = self._settings
        model = request.model
        if model is not None:
            if model in settings.tiers:
                model = settings.tiers[model]
            elif model not in settings.tiers.values() and not settings.options.get(
                "allow_explicit_model", False
            ):
                raise ValueError(f"Unknown Codex model: {model}")
        effort_arguments: tuple[str, ...] = ()
        effort = request.effort
        if effort is not None:
            if not effort.strip():
                raise ValueError("Codex effort must be nonblank")
            if effort in {"low", "medium", "high", "xhigh"}:
                effort_arguments = ("-c", f'model_reasoning_effort="{effort}"')
            else:
                logger.warning("Unmapped Codex effort: %s", effort)
        self._session_id = None
        self._usage = Usage()
        self._thread_conflict = False
        self._identities.clear()
        return LaunchSpec(
            argv=(
                *settings.command,
                "--ask-for-approval",
                "never",
                "exec",
                "--json",
                "--sandbox",
                "workspace-write",
                "-C",
                str(request.root),
                *(("-m", model) if model is not None else ()),
                *effort_arguments,
                "--",
                request.prompt,
            ),
            env=dict(settings.environment),
            cwd=request.root,
            raw_format="codex-exec-json-v1",
        )

    def probe(self) -> DriverHealth:
        executable = sanitize_text(self._settings.command[0])[:1024]
        environment = dict(os.environ) | dict(self._settings.environment)
        for label, operation in (
            ("version", ("--version",)),
            ("authentication", ("login", "status")),
        ):
            try:
                exit_code, stdout, stderr = _run_probe_command(
                    (*self._settings.command, *operation), environment
                )
            except subprocess.TimeoutExpired:
                return DriverHealth(
                    False, f"{executable}: {label} check timed out after 5 seconds"
                )
            except OSError:
                return DriverHealth(False, f"{executable}: executable unavailable")
            if exit_code != 0:
                return _probe_failure(executable, label, exit_code, stdout, stderr)
            if label == "version":
                text = stdout.decode("utf-8", errors="replace")
                version = text.splitlines()[0] if text else ""
                if version != f"codex-cli {_PINNED_VERSION}":
                    detail = (
                        f"observed {sanitize_text(version[10:])[:1024]}"
                        if version.startswith("codex-cli ")
                        else "missing Codex version"
                    )
                    return DriverHealth(
                        False,
                        f"{executable}: {detail}; pinned {_PINNED_VERSION}; "
                        "refresh the Codex fixture contract",
                    )
        return DriverHealth(
            True, f"{executable}: Codex {_PINNED_VERSION}; authentication verified"
        )

    def decode(self, raw_line: str) -> tuple[Observation, ...]:
        timestamp = datetime.now(UTC)
        kind = ObservationType.RAW_UNKNOWN
        payload: dict[str, JSONValue] = {
            "reason": "Malformed or unsupported Codex record",
            "raw_sha256": hashlib.sha256(raw_line.encode()).hexdigest(),
            "preview": sanitize_text(raw_line)[:512],
        }
        try:
            record = json.loads(raw_line)
        except (ValueError, RecursionError):
            record = None
        if isinstance(record, dict):
            event = record.get("type")
            if event == "thread.started":
                thread_id = record.get("thread_id")
                if isinstance(thread_id, str) and thread_id:
                    kind = ObservationType.SESSION_STARTED
                    started = replace(
                        self._observation(kind, {}, timestamp),
                        session_id=thread_id,
                    )
                    conflict = self._session_id not in (None, thread_id)
                    self._thread_conflict = self._thread_conflict or conflict
                    usage = Usage() if conflict else self._usage
                    self._session_id = thread_id
                    self._usage = usage
                    return (started,)
            elif event == "turn.started":
                kind = ObservationType.ACTIVITY_MESSAGE
                payload = {"kind": "turn"}
            elif event in ("item.started", "item.updated", "item.completed"):
                try:
                    return self._item_observations(
                        record.get("item"), event, timestamp, payload
                    )
                except (ValueError, RecursionError):
                    payload["reason"] = "Malformed or invalid JSON in Codex item"
            elif event == "turn.completed":
                return self._usage_observations(record.get("usage"), timestamp, payload)
            elif event in ("error", "turn.failed"):
                failure = self._failure_observations(record, event, timestamp)
                if failure is not None:
                    return failure
        return (self._observation(kind, payload, timestamp),)

    def _failure_observations(
        self,
        record: dict[str, JSONValue],
        event: str,
        timestamp: datetime,
    ) -> tuple[Observation, ...] | None:
        source = record if event == "error" else record.get("error")
        detail = source.get("message") if isinstance(source, dict) else None
        if isinstance(detail, str):
            failure_class = classify_failure(detail)
            reset = failure_reset(detail, timestamp)
            detail = bounded_detail(detail)
            reset_at = reset.isoformat() if reset is not None else None
            if event == "error":
                return (
                    self._observation(
                        ObservationType.ACTIVITY_MESSAGE,
                        {
                            "kind": "error",
                            "detail": detail,
                            "failure_class": failure_class.value,
                            "reset_at": reset_at,
                        },
                        timestamp,
                    ),
                )
            terminal = self._observation(
                ObservationType.SESSION_FAILED,
                {"failure_class": failure_class.value, "detail": detail},
                timestamp,
            )
            if failure_class == FailureClass.RATE_LIMIT:
                return (
                    terminal,
                    self._observation(
                        ObservationType.RATE_LIMIT_STARTED,
                        {"reset_at": reset_at, "window": None, "detail": detail},
                        timestamp,
                    ),
                )
            return (terminal,)
        return None

    def _usage_observations(
        self,
        native: object,
        timestamp: datetime,
        raw_payload: dict[str, JSONValue],
    ) -> tuple[Observation, ...]:
        snapshot, gap = turn_usage(native)
        if self._thread_conflict:
            gap = "; ".join(
                reason for reason in (gap, "Conflicting thread identity") if reason
            )
        values = asdict(self._usage)
        for name, value in asdict(snapshot).items():
            if name == "estimated":
                values[name] = values[name] or value
            elif value is not None:
                previous = values[name]
                values[name] = value if previous is None else max(previous, value)
        cumulative = Usage(**values)
        serialized = asdict(cumulative)
        observations = [
            self._observation(
                ObservationType.USAGE_UPDATED,
                {
                    "usage": serialized,
                    "identity": f"thread:{self._session_id or 'unknown'}",
                },
                timestamp,
            ),
            self._observation(
                ObservationType.SESSION_COMPLETED, {"usage": serialized}, timestamp
            ),
        ]
        if gap is not None:
            observations.append(
                self._observation(
                    ObservationType.RAW_UNKNOWN,
                    raw_payload | {"reason": gap},
                    timestamp,
                )
            )
        self._usage = cumulative
        self._thread_conflict = False
        return tuple(observations)

    def _item_observations(
        self,
        item: object,
        event: str,
        timestamp: datetime,
        raw_payload: dict[str, JSONValue],
    ) -> tuple[Observation, ...]:
        activity = item_activity(item)
        if activity is not None:
            return (
                self._observation(
                    ObservationType.ACTIVITY_MESSAGE, activity, timestamp
                ),
            )
        tool = item_tool(item, event)
        if tool is None:
            return (
                self._observation(ObservationType.RAW_UNKNOWN, raw_payload, timestamp),
            )
        kind, payload = tool
        observations = [self._observation(kind, payload, timestamp)]
        projected, has_unknown = item_lanes(
            item,
            {
                lane_id
                for (category, lane_id), done in self._identities.items()
                if category == "lane" and not done
            },
        )
        if has_unknown:
            observations.append(
                self._observation(ObservationType.RAW_UNKNOWN, raw_payload, timestamp)
            )
        for lane_id, lane_kind, lane_payload in projected:
            if self._identities.get(("lane", lane_id)):
                continue
            if (
                lane_kind == ObservationType.LANE_PROGRESS
                and ("lane", lane_id) not in self._identities
            ):
                lane_kind = ObservationType.LANE_STARTED
            observations.append(
                self._observation(lane_kind, lane_payload, timestamp, lane_id)
            )
        gaps = self._remember(observations, raw_payload, timestamp)
        return (*gaps, *observations)

    def _remember(
        self,
        observations: list[Observation],
        raw_payload: dict[str, JSONValue],
        timestamp: datetime,
    ) -> list[Observation]:
        gaps: list[Observation] = []
        identities = self._identities.copy()
        for observation in observations:
            if observation.lane_id is not None:
                identity = ("lane", observation.lane_id)
            elif observation.type.startswith("tool."):
                tool_id = observation.payload["tool_id"]
                assert isinstance(tool_id, str)
                identity = ("item", tool_id)
            else:
                continue
            if identity not in identities and len(identities) == 4096:
                evicted = next(
                    (key for key, done in identities.items() if done),
                    next(iter(identities)),
                )
                gap_payload = raw_payload | {
                    "reason": "Identity capacity gap; evicted "
                    + evicted[0]
                    + " "
                    + sanitize_text(evicted[1])[:512]
                }
                gaps.append(
                    self._observation(
                        ObservationType.RAW_UNKNOWN, gap_payload, timestamp
                    )
                )
                del identities[evicted]
            identities[identity] = observation.type in (
                ObservationType.TOOL_COMPLETED,
                ObservationType.TOOL_FAILED,
                ObservationType.LANE_COMPLETED,
                ObservationType.LANE_FAILED,
            )
        self._identities = identities
        return gaps

    def _observation(
        self,
        kind: ObservationType,
        payload: dict[str, JSONValue],
        timestamp: datetime,
        lane_id: str | None = None,
    ) -> Observation:
        return Observation(
            protocol_version=PROTOCOL_VERSION,
            timestamp=timestamp,
            provider=self.name,
            run_id=self._run_id,
            session_id=self._session_id,
            lane_id=lane_id,
            type=kind,
            payload=payload,
        )

    def summarize(
        self, observations: Iterable[Observation], exit_code: int
    ) -> SessionSummary:
        reduction = reduce_session(observations, exit_code)
        if any(
            observation.type
            in (
                ObservationType.SESSION_COMPLETED,
                ObservationType.SESSION_FAILED,
            )
            for observation in reduction.observations
        ):
            return reduction.summary
        for observation in reversed(reduction.observations):
            payload = observation.payload
            if (
                observation.type == ObservationType.ACTIVITY_MESSAGE
                and payload.get("kind") == "error"
                and "failure_class" in payload
            ):
                failure_class = FailureClass(str(payload["failure_class"]))
                fallback = [
                    replace(
                        observation,
                        type=ObservationType.SESSION_FAILED,
                        payload={
                            "failure_class": failure_class.value,
                            "detail": payload["detail"],
                        },
                    )
                ]
                if failure_class == FailureClass.RATE_LIMIT:
                    fallback.append(
                        replace(
                            observation,
                            type=ObservationType.RATE_LIMIT_STARTED,
                            payload={
                                "reset_at": payload.get("reset_at"),
                                "window": None,
                                "detail": payload["detail"],
                            },
                        )
                    )
                return reduce_session(
                    (*reduction.observations, *fallback), exit_code
                ).summary
        return reduction.summary

    def default_prompt(self, phase: str) -> str:
        if phase not in {"build", "review", "done"}:
            raise ValueError(f"Unknown Codex prompt phase: {phase}")
        return f"$run-autopilot\n{_DEFAULT_PROMPT}"

"""Provider edge: construct the configured built-in driver."""

from __future__ import annotations

from dataclasses import replace
from pathlib import Path
from uuid import uuid4

from ovcaq.config import AgentSettings, agent_settings
from ovcaq.drivers.base import AgentDriver, LaunchRequest, LaunchSpec
from ovcaq.drivers.claude import ClaudeDriver
from ovcaq.drivers.codex import CodexDriver
from ovcaq.errors import CommandError, ErrorCode


def _map_model_to_tier(
    settings: AgentSettings, request: LaunchRequest
) -> LaunchRequest:
    tiers = {model: tier for tier, model in settings.tiers.items()}
    if request.model in tiers:
        return replace(request, model=tiers[request.model])
    return request


class _ResolvedModelClaudeDriver(ClaudeDriver):
    """Map the supervisor's resolved model back to its configured tier key."""

    def build_launch(self, request: LaunchRequest) -> LaunchSpec:
        return super().build_launch(_map_model_to_tier(self._settings, request))


class _ResolvedModelCodexDriver(CodexDriver):
    """Map the supervisor's resolved model back to its configured tier key."""

    def build_launch(self, request: LaunchRequest) -> LaunchSpec:
        return super().build_launch(_map_model_to_tier(self._settings, request))


def build_driver(root: Path, name: str | None) -> AgentDriver:
    agent = agent_settings(root, name=name)
    if agent.name == "claude":
        return _ResolvedModelClaudeDriver(agent, run_id=uuid4().hex)
    if agent.name == "codex":
        return _ResolvedModelCodexDriver(agent, run_id=uuid4().hex)
    raise CommandError(ErrorCode.RUNTIME_FORMAT, f"unknown agent: {agent.name}")

"""Claude command construction and normalized session summaries."""

import hashlib
import json
import math
import os
import shutil
from collections import OrderedDict
from collections.abc import Iterable
from dataclasses import asdict
from datetime import UTC, datetime
from typing import Any

from ovcaq.config import AgentSettings
from ovcaq.drivers.base import DriverHealth, LaunchRequest, LaunchSpec
from ovcaq.drivers.claude_events import (
    banner_reset,
    block_payload,
    failure_payload,
    init_payload,
    rate_limit_payload,
    record_timestamp,
    task_payload,
)
from ovcaq.events import (
    PROTOCOL_VERSION,
    Observation,
    ObservationType,
    SessionSummary,
    Usage,
    reduce_session,
    sanitize_text,
)
from ovcaq.events.model import JSONValue


class ClaudeDriver:
    name = "claude"

    def __init__(self, settings: AgentSettings, *, run_id: str) -> None:
        options = settings.options
        if options.keys() - {
            "permission_mode",
            "allow_explicit_model",
            "fallback_model",
        }:
            raise ValueError("Unknown Claude driver option")
        if options.get("permission_mode") != "auto":
            raise ValueError("Claude permission_mode must be auto")
        if type(options.get("allow_explicit_model", False)) is not bool:
            raise ValueError("allow_explicit_model must be a boolean")
        if "fallback_model" in options and (
            not isinstance(options["fallback_model"], str)
            or not options["fallback_model"].strip()
        ):
            raise ValueError("fallback_model must be a nonblank string")
        defaults = {
            "CLAUDE_UNATTENDED": "1",
            "CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS": "0",
        }
        for key, value in settings.environment.items():
            if key in defaults and value != defaults[key]:
                raise ValueError(f"Cannot override fixed Claude environment key: {key}")
        self._settings = settings
        self._run_id = run_id
        self._environment = defaults | dict(settings.environment)
        self._session_id: str | None = None
        self._limit_live = False
        self._messages: OrderedDict[str, dict[str, int]] = OrderedDict()
        self._message_totals: dict[str, int] = {}
        # Evicted IDs remain in a fixed Bloom filter. False positives can
        # conservatively undercount new messages, but never inflate replays.
        self._evicted = bytearray(1024 * 1024)

    def default_prompt(self, phase: str) -> str:
        if phase not in {"build", "review", "done"}:
            raise ValueError(f"Unknown phase: {phase}")
        return "/autopilot:run-autopilot"

    def probe(self) -> DriverHealth:
        command = self._settings.command[0]
        path = self._environment.get("PATH", os.environ.get("PATH", os.defpath))
        resolved = shutil.which(command, path=path)
        if resolved is None:
            return DriverHealth(
                False, f"Command is missing or not executable: {command}"
            )
        return DriverHealth(
            True, f"Executable command: {resolved}; permission_mode=auto"
        )

    def build_launch(self, request: LaunchRequest) -> LaunchSpec:
        settings = self._settings
        model = request.model
        if model is None:
            raise ValueError("Claude requires a model tier")
        if model in settings.tiers:
            model = settings.tiers[model]
        elif not settings.options.get("allow_explicit_model", False):
            raise ValueError(f"Unknown Claude model tier: {model}")
        if request.effort is None or not request.effort.strip():
            raise ValueError("Claude requires a nonblank effort")
        fallback_arguments: tuple[str, ...] = ()
        fallback_tier = settings.options.get("fallback_model")
        if isinstance(fallback_tier, str):
            if fallback_tier not in settings.tiers:
                raise ValueError(f"Unknown Claude fallback tier: {fallback_tier}")
            fallback_model = settings.tiers[fallback_tier]
            if fallback_model != model:
                fallback_arguments = ("--fallback-model", fallback_model)
        return LaunchSpec(
            argv=(
                *settings.command,
                "-p",
                "--permission-mode",
                "auto",
                "--model",
                model,
                "--effort",
                request.effort,
                *fallback_arguments,
                "--output-format",
                "stream-json",
                "--verbose",
                request.prompt,
            ),
            env=dict(self._environment),
            cwd=request.root,
            raw_format="claude-stream-json-v1",
        )

    def decode(self, raw_line: str) -> tuple[Observation, ...]:
        now = datetime.now(UTC)
        timestamp = now
        observations: list[Observation] = []
        try:
            record = json.loads(raw_line)
        except (ValueError, RecursionError):
            record = None
        if isinstance(record, dict):
            session_id = record.get("session_id")
            if isinstance(session_id, str) and session_id:
                self._session_id = session_id
            lane_id = record.get("parent_tool_use_id")
            if not isinstance(lane_id, str) or not lane_id:
                lane_id = None
            timestamp = record_timestamp(record, now)
            observations = self._decode_record(record, timestamp, now, lane_id)
        if not observations:
            observations.append(
                self._observation(
                    ObservationType.RAW_UNKNOWN,
                    {
                        "reason": "unrecognized Claude stream record",
                        "raw_sha256": hashlib.sha256(
                            raw_line.encode("utf-8", errors="replace")
                        ).hexdigest(),
                        "preview": sanitize_text(raw_line)[:512],
                    },
                    timestamp,
                )
            )
        return tuple(observations)

    def _decode_record(
        self,
        record: dict[str, Any],
        timestamp: datetime,
        now: datetime,
        lane_id: str | None,
    ) -> list[Observation]:
        kind, subtype = record.get("type"), record.get("subtype")
        if kind == "system" and subtype == "init":
            return [
                self._observation(
                    ObservationType.SESSION_STARTED, init_payload(record), timestamp
                )
            ]
        if kind in ("assistant", "user"):
            return self._decode_message(record, timestamp, lane_id)
        if kind == "system" and subtype in (
            "task_started",
            "task_progress",
            "task_notification",
            "task_updated",
            "background_tasks_changed",
        ):
            return self._decode_tasks(record, timestamp)
        if kind == "rate_limit_event":
            info = record.get("rate_limit_info")
            projected = (
                rate_limit_payload(info, now) if isinstance(info, dict) else None
            )
            if projected is not None:
                event, payload = projected
                if event == ObservationType.RATE_LIMIT_STARTED:
                    self._limit_live = payload["reset_at"] is not None
                elif event == ObservationType.RATE_LIMIT_CLEARED:
                    self._limit_live = False
                return [self._observation(event, payload, timestamp)]
        if kind == "result":
            return self._decode_result(record, timestamp)
        return []

    def _decode_message(
        self,
        record: dict[str, Any],
        timestamp: datetime,
        lane_id: str | None,
    ) -> list[Observation]:
        observations: list[Observation] = []
        message = record.get("message")
        if not isinstance(message, dict):
            return observations
        message_id = message.get("id")
        metadata: dict[str, JSONValue] = {}
        if isinstance(message_id, str) and message_id:
            metadata["message_id"] = message_id
        blocks = message.get("content")
        for block in blocks if isinstance(blocks, list) else ():
            if not isinstance(block, dict):
                continue
            projected = block_payload(block, metadata)
            if projected is not None:
                event, payload = projected
                observations.append(
                    self._observation(event, payload, timestamp, lane_id)
                )
        usage = message.get("usage")
        if isinstance(usage, dict) and metadata:
            identity = f"message:{message_id}"
            snapshot = self._update_usage(usage, identity)
            observations.append(
                self._observation(
                    ObservationType.USAGE_UPDATED,
                    {"identity": identity, "usage": snapshot},
                    timestamp,
                    lane_id,
                )
            )
        return observations

    def _decode_tasks(
        self,
        record: dict[str, Any],
        timestamp: datetime,
    ) -> list[Observation]:
        observations: list[Observation] = []
        subtype = record.get("subtype")
        tasks = (
            record.get("tasks") if subtype == "background_tasks_changed" else [record]
        )
        for task in tasks if isinstance(tasks, list) else ():
            if not isinstance(task, dict):
                continue
            projected = task_payload(task, subtype)
            if projected is not None:
                event, payload, task_id = projected
                observations.append(
                    self._observation(event, payload, timestamp, task_id)
                )
        return observations

    def _decode_result(
        self,
        record: dict[str, Any],
        timestamp: datetime,
    ) -> list[Observation]:
        observations: list[Observation] = []
        usage = record.get("usage")
        snapshot = None
        if isinstance(usage, dict):
            identity = f"result:{self._session_id}"
            snapshot = self._update_usage(
                usage, identity, cumulative=True, cost=record.get("total_cost_usd")
            )
            observations.append(
                self._observation(
                    ObservationType.USAGE_UPDATED,
                    {"identity": identity, "usage": snapshot},
                    timestamp,
                )
            )
        if record.get("is_error") is True or record.get("subtype") != "success":
            event = ObservationType.SESSION_FAILED
            payload = failure_payload(record.get("result"))
            reset_at = None
            if payload["failure_class"] == "rate_limit" and not self._limit_live:
                reset_at = banner_reset(
                    str(record.get("result")), timestamp, datetime.now(UTC)
                )
            if reset_at is not None:
                observations.append(
                    self._observation(
                        ObservationType.RATE_LIMIT_STARTED,
                        {
                            "reset_at": reset_at,
                            "window": None,
                            "detail": payload["detail"],
                        },
                        timestamp,
                    )
                )
        else:
            event = ObservationType.SESSION_COMPLETED
            payload = {"usage": snapshot} if snapshot is not None else {}
        observations.append(self._observation(event, payload, timestamp))
        return observations

    def _observation(
        self,
        kind: ObservationType,
        payload: dict[str, JSONValue],
        timestamp: datetime,
        lane_id: str | None = None,
    ) -> Observation:
        return Observation(
            protocol_version=PROTOCOL_VERSION,
            timestamp=timestamp,
            provider=self.name,
            run_id=self._run_id,
            session_id=self._session_id,
            lane_id=lane_id,
            type=kind,
            payload=payload,
        )

    def _update_usage(
        self,
        values: dict[str, object],
        identity: str,
        *,
        cumulative: bool = False,
        cost: object = None,
    ) -> dict[str, JSONValue]:
        counters = {
            name: value
            for name, value in values.items()
            if name
            in (
                "input_tokens",
                "output_tokens",
                "cache_creation_input_tokens",
                "cache_read_input_tokens",
                "tool_uses",
            )
            and type(value) is int
            and value >= 0
        }
        if not cumulative:
            self._remember_usage(identity, counters)
            counters = self._message_totals
        snapshot = asdict(Usage(estimated=not cumulative))
        snapshot.update(counters)
        if (
            isinstance(cost, (int, float))
            and not isinstance(cost, bool)
            and math.isfinite(cost)
            and cost >= 0
        ):
            snapshot["cost_usd"] = float(cost)
        return snapshot

    def _remember_usage(self, identity: str, counters: dict[str, int]) -> None:
        previous = self._messages.get(identity)
        digest = hashlib.sha256(identity.encode()).digest()
        indices = [
            int.from_bytes(digest[index : index + 4]) % (len(self._evicted) * 8)
            for index in range(0, 16, 4)
        ]
        seen = all(self._evicted[index // 8] & (1 << (index % 8)) for index in indices)
        if previous is not None or not seen:
            contribution = dict(previous or {})
            for name, value in counters.items():
                old = contribution.get(name, 0)
                contribution[name] = max(old, value)
                self._message_totals[name] = self._message_totals.get(name, 0) + max(
                    0, value - old
                )
            self._messages[identity] = contribution
            self._messages.move_to_end(identity)
            if len(self._messages) > 4096:
                evicted, _ = self._messages.popitem(last=False)
                digest = hashlib.sha256(evicted.encode()).digest()
                for offset in range(0, 16, 4):
                    index = int.from_bytes(digest[offset : offset + 4]) % (
                        len(self._evicted) * 8
                    )
                    self._evicted[index // 8] |= 1 << (index % 8)

    def summarize(
        self, observations: Iterable[Observation], exit_code: int
    ) -> SessionSummary:
        return reduce_session(observations, exit_code).summary

    explicit: Mapping[str, object],
) -> SupervisorPolicy:
    from ovcaq.runtime.decision import SupervisorPolicy

    if "policy" in explicit:
        policy = explicit["policy"]
        if not isinstance(policy, SupervisorPolicy):
            raise ConfigurationError("policy must be SupervisorPolicy")
    else:
        values: dict[str, object] = {
            "died_retries": 1,
            "connectivity_retries": 3,
            "rate_limit_retries": 3,
            "connectivity_wait_seconds": 1800,
            "rate_limit_wait_seconds": 21600,
            "phase_repeat_limit": 5,
        }
        for config in (user, project):
            configured = _table(config, "supervisor")
            if configured.keys() - values.keys():
                raise ConfigurationError("unknown supervisor policy fields")
            values.update(configured)
        for key, value in values.items():
            if key.endswith("wait_seconds"):
                if (
                    isinstance(value, bool)
                    or not isinstance(value, (int, float))
                    or not math.isfinite(value)
                    or value <= 0
                ):
                    raise ConfigurationError(f"{key} must be finite and positive")
            elif type(value) is not int or value < (
                1 if key == "phase_repeat_limit" else 0
            ):
                raise ConfigurationError(f"{key} must be an integer in range")
        policy = SupervisorPolicy(
            died_retries=cast(int, values["died_retries"]),
            connectivity_retries=cast(int, values["connectivity_retries"]),
            rate_limit_retries=cast(int, values["rate_limit_retries"]),
            connectivity_wait_seconds=cast(float, values["connectivity_wait_seconds"]),
            rate_limit_wait_seconds=cast(float, values["rate_limit_wait_seconds"]),
            phase_repeat_limit=cast(int, values["phase_repeat_limit"]),
        )
    return policy


def _supervisor_phases(
    user: Mapping[str, object],
    project: Mapping[str, object],
    explicit: Mapping[str, object],
) -> Mapping[str, PhaseSettings]:
    if "phases" in explicit:
        phases = explicit["phases"]
        if (
            not isinstance(phases, Mapping)
            or phases.keys() != _PHASES
            or any(not isinstance(value, PhaseSettings) for value in phases.values())
        ):
            raise ConfigurationError(
                "phases must map every routable phase to PhaseSettings"
            )
    else:
        from ovcaq.drivers import DEFAULT_PHASE_TIERS

        user_phases = _phase_tables(user)
        project_phases = _phase_tables(project)
        configured_phases: dict[str, PhaseSettings] = {}
        for phase in ("build", "review", "done"):
            phase_values = {
                "tier": DEFAULT_PHASE_TIERS[phase],
                "effort": "high",
                "timeout_seconds": 10800 if phase == "review" else 7200,
                **user_phases.get(phase, {}),
                **project_phases.get(phase, {}),
            }
            configured_phases[phase] = PhaseSettings(
                cast(str, phase_values["tier"]),
                cast(Effort, phase_values["effort"]),
                cast(int, phase_values["timeout_seconds"]),
            )
        phases = configured_phases
    return cast(Mapping[str, PhaseSettings], phases)


def supervisor_settings(root: Path, **explicit: object) -> SupervisorSettings:
    """Resolve runtime, retry policy, and provider-neutral phase defaults."""
    if explicit.keys() - {"runtime", "policy", "phases"}:
        raise ConfigurationError("unknown supervisor settings")
    root = _trusted_path(root)
    config_home = _trusted_path(
        Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
    )
    user = _read_config(config_home / "ovcaq/config.toml")
    project = _read_config(root / CONFIG_NAME)
    runtime = explicit["runtime"] if "runtime" in explicit else runtime_settings(root)
    if not isinstance(runtime, RuntimeSettings):
        raise ConfigurationError("runtime must be RuntimeSettings")
    policy = _supervisor_policy(user, project, explicit)
    phases = _supervisor_phases(user, project, explicit)
    return SupervisorSettings(
        runtime, policy, phases, _capability_timeouts(user, project)
    )


def resolve_phase_route(
    root: Path,
    phase: str,
    *,
    agent: str | None = None,
    phase_settings: PhaseSettings | None = None,
) -> ResolvedPhaseRoute:
    """Resolve a phase tier and literal prompt for the selected agent."""
    if phase not in _PHASES:
        raise ConfigurationError(f"Unknown route phase: {phase}")
    selected = agent_settings(root, name=agent)
    root = _trusted_path(root)
    config_home = _trusted_path(
        Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
    )
    overrides: dict[str, object] = {}
    for path in (config_home / "ovcaq/config.toml", root / CONFIG_NAME):
        config = _read_config(path)
        selected_config = _table(_table(config, "agents"), selected.name)
        overrides.update(_phase_tables(selected_config, agent=True).get(phase, {}))
    neutral = (
        supervisor_settings(root).phases[phase]
        if phase_settings is None
        else phase_settings
    )
    resolved = PhaseSettings(
        cast(str, overrides.get("tier", neutral.tier)),
        cast(Effort, overrides.get("effort", neutral.effort)),
        neutral.timeout_seconds,
    )
    if resolved.tier not in selected.tiers:
        raise ConfigurationError(f"Unknown agent tier: {resolved.tier}")
    return ResolvedPhaseRoute(
        selected.name,
        phase,
        resolved.tier,
        selected.tiers[resolved.tier],
        resolved.effort,
        resolved.timeout_seconds,
        selected.prompts.get(phase),
    )

"""Provider-neutral driver records, protocol, and plugin discovery."""

from collections.abc import Callable, Iterable, Mapping
from dataclasses import dataclass
from importlib import metadata
from pathlib import Path
from types import MappingProxyType
from typing import Protocol

from ovcaq.events import Observation, SessionSummary

DRIVER_API_VERSION = 2


def _require_string(value: object, field: str) -> None:
    if not isinstance(value, str):
        raise TypeError(f"{field} must be a string")
    if not value:
        raise ValueError(f"{field} must not be empty")


@dataclass(frozen=True, slots=True)
class LaunchRequest:
    root: Path
    phase: str
    prompt: str
    model: str | None
    effort: str | None
    timeout_seconds: int
    session_dir: Path

    def __post_init__(self) -> None:
        for field in ("root", "session_dir"):
            if not isinstance(getattr(self, field), Path):
                raise TypeError(f"{field} must be a Path")
        for field in ("phase", "prompt"):
            _require_string(getattr(self, field), field)
        for field in ("model", "effort"):
            value = getattr(self, field)
            if value is not None:
                _require_string(value, field)
        if type(self.timeout_seconds) is not int:
            raise TypeError("timeout_seconds must be an integer")
        if self.timeout_seconds <= 0:
            raise ValueError("timeout_seconds must be positive")


@dataclass(frozen=True, slots=True)
class LaunchSpec:
    argv: tuple[str, ...]
    env: Mapping[str, str]
    cwd: Path
    raw_format: str

    def __post_init__(self) -> None:
        if not isinstance(self.argv, tuple):
            raise TypeError("argv must be a tuple")
        if not self.argv:
            raise ValueError("argv must not be empty")
        for argument in self.argv:
            _require_string(argument, "argv argument")
        if not isinstance(self.env, Mapping):
            raise TypeError("env must be a mapping")
        for key, value in self.env.items():
            _require_string(key, "env key")
            _require_string(value, "env value")
        object.__setattr__(self, "env", MappingProxyType(dict(self.env)))
        if not isinstance(self.cwd, Path):
            raise TypeError("cwd must be a Path")
        _require_string(self.raw_format, "raw_format")


@dataclass(frozen=True, slots=True)
class DriverHealth:
    healthy: bool
    detail: str

    def __post_init__(self) -> None:
        if type(self.healthy) is not bool:
            raise TypeError("healthy must be a boolean")
        if not isinstance(self.detail, str):
            raise TypeError("detail must be a string")


class AgentDriver(Protocol):
    name: str

    def default_prompt(self, phase: str) -> str: ...

    def probe(self) -> DriverHealth: ...

    def build_launch(self, request: LaunchRequest) -> LaunchSpec: ...

    def decode(self, raw_line: str) -> Iterable[Observation]: ...

    def summarize(
        self, observations: Iterable[Observation], exit_code: int
    ) -> SessionSummary: ...


DriverFactory = Callable[[], AgentDriver]


@dataclass(frozen=True, slots=True)
class DriverPlugin:
    api_version: int
    factory: DriverFactory

    def __post_init__(self) -> None:
        if type(self.api_version) is not int:
            raise TypeError("api_version must be an integer")
        if not callable(self.factory):
            raise TypeError("factory must be callable")


class DriverDiscoveryError(RuntimeError):
    """A driver could not be loaded, constructed, or verified."""


class IncompatibleDriverError(DriverDiscoveryError):
    """A plugin declares an unsupported driver API version."""


class DuplicateDriverError(DriverDiscoveryError):
    """More than one plugin declares the same driver name."""


def _register_driver(
    discovered: dict[str, AgentDriver],
    candidate: object,
    source: str,
    advertised_name: str | None = None,
) -> None:
    if not isinstance(candidate, DriverPlugin):
        raise DriverDiscoveryError(f"{source} must provide a DriverPlugin")
    if candidate.api_version != DRIVER_API_VERSION:
        raise IncompatibleDriverError(
            f"{source} uses driver API {candidate.api_version}; "
            f"expected {DRIVER_API_VERSION}"
        )
    try:
        driver = candidate.factory()
    except Exception as exc:
        raise DriverDiscoveryError(f"{source} factory failed: {exc}") from exc
    name = driver.name
    if not isinstance(name, str) or not name:
        raise DriverDiscoveryError(f"{source} has an invalid driver name: {name!r}")
    if advertised_name is not None and name != advertised_name:
        raise DriverDiscoveryError(
            f"{source} advertises {advertised_name!r} but returned {name!r}"
        )
    if name in discovered:
        raise DuplicateDriverError(f"Duplicate driver name: {name!r} ({source})")
    try:
        health = driver.probe()
    except Exception as exc:
        raise DriverDiscoveryError(
            f"Driver {name!r} from {source} probe failed: {exc}"
        ) from exc
    if not health.healthy:
        raise DriverDiscoveryError(
            f"Driver {name!r} from {source} is unhealthy: {health.detail}"
        )
    discovered[name] = driver


def discover_drivers(
    builtins: Iterable[DriverPlugin],
    *,
    entry_points: Iterable[metadata.EntryPoint] | None = None,
) -> Mapping[str, AgentDriver]:
    """Construct and probe each plugin, returning an immutable ordered registry."""
    discovered: dict[str, AgentDriver] = {}
    for index, candidate in enumerate(builtins):
        _register_driver(discovered, candidate, f"builtin {index}")
    if entry_points is None:
        entry_points = metadata.entry_points(group="ovcaq.drivers")
    for entry_point in sorted(entry_points, key=lambda entry: entry.name):
        source = f"entry point {entry_point.name!r}"
        try:
            loaded = entry_point.load()
        except Exception as exc:
            raise DriverDiscoveryError(f"Could not load {source}: {exc}") from exc
        _register_driver(discovered, loaded, source, entry_point.name)
    return MappingProxyType(discovered)

    if (target.st_dev, target.st_ino) != (info.st_dev, info.st_ino):
